// Exercises the real Pi extension loader, the real tool_call hook, and the
// real bash tool in one chain. No model or provider call is made.
//
// Usage: node pi_tool_guard_chain.mjs <tool-guard-extension.mjs>
// The extension is generated by the daemon with MULTICA_PI_BASH_TIMEOUT=1s.
import { execFileSync } from "node:child_process";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const extensionPath = process.argv[2];
if (!extensionPath) {
  console.error("missing extension path");
  process.exit(2);
}
const root = process.env.PI_CODING_AGENT_ROOT ||
  "/usr/local/lib/node_modules/@mariozechner/pi-coding-agent";
const importDist = async (relative) => import(pathToFileURL(join(root, relative)).href);

const { loadExtensions } = await importDist("dist/core/extensions/loader.js");
const { ExtensionRunner } = await importDist("dist/core/extensions/runner.js");
const { createBashTool } = await importDist("dist/core/tools/bash.js");

const loaded = await loadExtensions([extensionPath], process.cwd());
if (loaded.errors.length > 0) {
  console.log(JSON.stringify({ ok: false, errors: loaded.errors }, null, 2));
  process.exit(1);
}
const runner = new ExtensionRunner(loaded.extensions, loaded.runtime, process.cwd());
const tool = createBashTool(process.cwd());

const HARD_DEADLINE_MS = 6000;
const results = [];

const cleanup = (marker) => {
  try {
    execFileSync("pkill", ["-9", "-f", marker], { stdio: "ignore" });
  } catch {
    // No survivor, which is the expected path.
  }
};
const survivors = (marker) => {
  try {
    const out = execFileSync("pgrep", ["-f", marker], { encoding: "utf8" }).trim();
    return out ? out.split("\n") : [];
  } catch {
    return [];
  }
};

const scenario = async (name, input, expect) => {
  const event = { toolName: "bash", toolCallId: name, input: { ...input } };
  const hookResult = await runner.emitToolCall(event);
  if (hookResult?.block) {
    throw new Error(name + ": hook blocked the call");
  }

  const controller = new AbortController();
  const hard = setTimeout(() => controller.abort(), HARD_DEADLINE_MS);
  const started = Date.now();
  let outcome;
  let message = "";
  let text = "";
  try {
    const result = await tool.execute(name, event.input, controller.signal, undefined, {});
    outcome = "success";
    text = (result.content || []).map((part) => part.text || "").join("");
  } catch (error) {
    outcome = "error";
    message = error instanceof Error ? error.message : String(error);
    text = message;
  } finally {
    clearTimeout(hard);
  }
  const elapsedSeconds = Number(((Date.now() - started) / 1000).toFixed(2));
  const marker = expect.marker;
  const survivorPids = marker ? survivors(marker) : [];
  if (marker) cleanup(marker);

  const record = {
    name,
    timeoutUsed: event.input.timeout,
    outcome,
    elapsedSeconds,
    survivorPids,
    message: message.slice(0, 400),
  };
  results.push(record);

  const failures = [];
  if (expect.timeoutUsed !== undefined && event.input.timeout !== expect.timeoutUsed) {
    failures.push(`timeoutUsed=${event.input.timeout}, want ${expect.timeoutUsed}`);
  }
  if (expect.outcome && outcome !== expect.outcome) {
    failures.push(`outcome=${outcome}, want ${expect.outcome}`);
  }
  if (expect.maxSeconds !== undefined && elapsedSeconds > expect.maxSeconds) {
    failures.push(`elapsed=${elapsedSeconds}s > ${expect.maxSeconds}s`);
  }
  if (expect.minSeconds !== undefined && elapsedSeconds < expect.minSeconds) {
    failures.push(`elapsed=${elapsedSeconds}s < ${expect.minSeconds}s`);
  }
  if (expect.messageIncludes && !text.includes(expect.messageIncludes)) {
    failures.push(`text does not include ${JSON.stringify(expect.messageIncludes)}`);
  }
  if (expect.noSurvivors && survivorPids.length > 0) {
    failures.push(`surviving pids ${survivorPids.join(",")}`);
  }
  if (failures.length > 0) {
    record.failures = failures;
    record.ok = false;
  } else {
    record.ok = true;
  }
};

// The guard was generated with MULTICA_PI_BASH_TIMEOUT=1s.
await scenario("omitted-budget-never-returns", { command: "sleep 691" }, {
  timeoutUsed: 1,
  outcome: "error",
  maxSeconds: 2.5,
  minSeconds: 0.8,
  messageIncludes: "Command timed out after 1 seconds",
  marker: "sleep 691",
  noSurvivors: true,
});

await scenario("continuous-output-does-not-extend-deadline", {
  command: "while true; do echo tick; sleep 0.2; done",
}, {
  timeoutUsed: 1,
  outcome: "error",
  maxSeconds: 2.5,
  messageIncludes: "tick",
});

await scenario("explicit-long-budget-preserved", {
  command: "sleep 1.2; echo done",
  timeout: 5,
}, {
  timeoutUsed: 5,
  outcome: "success",
  maxSeconds: 3,
  messageIncludes: "done",
});

await scenario("normal-finite-task-not-killed", {
  command: "sleep 0.3; echo ok",
}, {
  timeoutUsed: 1,
  outcome: "success",
  maxSeconds: 1.5,
  messageIncludes: "ok",
});

await scenario("explicit-short-budget-preserved", { command: "sleep 693", timeout: 2 }, {
  timeoutUsed: 2,
  outcome: "error",
  maxSeconds: 3.5,
  minSeconds: 1.8,
  messageIncludes: "Command timed out after 2 seconds",
  marker: "sleep 693",
  noSurvivors: true,
});

await scenario("command-error-is-visible", { command: "exit 3" }, {
  timeoutUsed: 1,
  outcome: "error",
  maxSeconds: 1.5,
  messageIncludes: "Command exited with code 3",
});

console.log(JSON.stringify({ ok: results.every((r) => r.ok), results }, null, 2));
process.exit(results.every((r) => r.ok) ? 0 : 1);
